type Canvas =
  | { preset: "portrait"; width: 480; scale: 3 }
  | { preset: "wide"; width: 720; scale: 2 };

const canvases: Canvas[] = [
  { preset: "portrait", width: 480, scale: 3 },
  { preset: "wide", width: 720, scale: 2 },
];

function outputWidth(canvas: Canvas): number {
  return canvas.width * canvas.scale;
}

for (const canvas of canvases) {
  if (outputWidth(canvas) !== 1440) {
    throw new Error(`Unexpected output width for ${canvas.preset}`);
  }
}
```

这段代码同时测试缩进、联合类型、模板字符串和多行代码块高度。

